                state[i] = i;
                i++;
        } while (i);

        ctx->x = ctx->y = 0;
        index1 = index2 = 0;
        do {
                index2 = key[index1] + state[i] + index2;
                xchg(&state[i], &state[index2]);
                index1++;
                if (index1 >= len)
                        index1 = 0;
                i++;
        } while (i);
}

void    rc4 (uchar *data, int len, rc4_ctx *ctx)
{
        uchar   *state = ctx->state;
        uchar   x = ctx->x;
        uchar   y = ctx->y;
        int     i;

        for (i = 0; i < len; i++) {
                uchar xor;

                x++;
                y = state[x] + y;
                xchg(&state[x], &state[y]);

                xor = state[x] + state[y];
                data[i] ^= state[xor];
        }

        ctx->x = x;
        ctx->y = y;
}

