	memaddr = allocaddr;

	for (addr = startaddr; addr < (startaddr + dumpsize); addr += 4, memaddr++) {
		if (read_value_at_address(addr, &val) != 0) {
			LOGV("kerneldump failed: %s.\n", strerror(errno));
			return NULL;
		}
		*memaddr = val;
	}

	return allocaddr;
}

