        perror("pipe");  
        return 1;  
    }  

    for (i = 0; i < (int) sizeof(data) ; i++) {  
        char buf[256];  
        buf[0] = 0;  
        if (data[i]) {  
            if (write(pipefd[1], buf, data[i]) != data[i]) {  
                LOGV("error in write().\n");  
                break;  
            }  
        }  

        if (ioctl(pipefd[0], FIONREAD, (void *)(address + i)) == -1) {  
